  "supportive_card_ids": ["C01", "C11", "C13", "C04", "C05", "C14", "C02", "C03", "C08", "C76"],
  "contradictory_card_ids": ["C22", "C109"],
  "prediction_basis_card_ids": ["C01", "C11", "C13", "C04", "C05", "C14", "C02", "C03", "C08", "C76"],
  "claims": [
    {
      "claim": "The query is a small basic secondary amine with a primary carboxamide; the closest reference, pramipexole, shares the tetrahydro-fused bicyclic amine scaffold and has accepted absolute oral bioavailability >90% despite full ionization at physiological pH (C01), with measurable oral exposure after extended-release dosing (C76).",
      "card_ids": ["C01", "C76"]
    },
    {
      "claim": "Other ionized small-molecule references exceed the 20% threshold: 5-HTP 49% (C11), labetalol 33% in controls and 63% in cirrhosis (C13, C16, C17, C24), AZD0837 22-55% (C04, C05, C14, C20), ebastine ~40% (C02), and PF-05241328 38% (C03, C08).",
      "card_ids": ["C11", "C13", "C16", "C17", "C24", "C04", "C05", "C14", "C20", "C02", "C03", "C08"]
    },
    {
      "claim": "L4 solubility records for basic/primary-amide compounds show high aqueous solubility at low pH (galunisertib 4.81 mg/mL at pH 2.65, C129; >=20 mg/mL at pH<3, C115; 4.811 mg/mL at pH 2, C100) and small basic drugs can be freely soluble (C128), supporting that ionization does not preclude dissolution.",
      "card_ids": ["C129", "C115", "C100", "C128"]
    },
    {
      "claim": "The only below-threshold measured F among reference contexts is isradipine's non-cirrhotic baseline of 16% (C22), but it is condition-specific and structurally dissimilar (dihydropyridine ester), so it does not transfer to the query.",
      "card_ids": ["C22"]
    },
    {
      "claim": "The L4 permeability caution (low passive PAMPA for a different larger indole amide, C109) is not a query measurement and does not affirmatively establish F<20%, especially since active transport can mediate absorption of ionized small molecules.",
      "card_ids": ["C109"]
    }
  ],
  "new_evidence_assessment": [
    {
      "family": "intestinal_absorption_permeability",
      "applicability": "low",
      "direction": "neutral_or_unclear",
      "decision_effect": "no_change",
      "card_ids": ["C128", "C129", "C115", "C100", "C109"]
    }
  ],
  "evidence_gaps": [
    "No direct measured oral bioavailability or IV-comparator AUC for the query molecule.",
    "No query-specific intestinal permeability or absorption measurement; L4 records are for other molecules.",
    "First-pass metabolism and transporter-mediated absorption for the query are not directly assessed.",
    "The low passive permeability record (C109) is for a structurally distinct molecule and cannot be transferred as affirmative low-F evidence.",
    "Solubility is likely favorable but alone does not establish F>=20%."
  ],
  "decision_summary": "L4 provides no direct query permeability or F measurement; solubility records for basic amide compounds are favorable but do not establish absorption, and the low passive permeability record is for an unrelated molecule. The high prediction remains supported by transferable L1 references (pramipexole >90%, 5-HTP 49%, labetalol 33-63%, AZD0837 22-55%) and L3 oral exposure; confidence remains moderate."
}

